/**
 * Render a component instance to HTML.
 *
 * @param  \Illuminate\View\Component  $component
 * @return string
 */
public static function renderComponent(Component $component)
{
    $data = $component->data();

    $view = value($component->resolveView(), $data);

    if ($view instanceof View) {
        return $view->with($data)->render();
    } elseif ($view instanceof Htmlable) {
        return $view->toHtml();
    } else {
        return Container::getInstance()
            ->make(ViewFactory::class)
            ->make($view, $data)
            ->render();
    }
}

/**
 * Store the blocks that do not receive compilation.
 *
 * @param  string  $value
 * @return string
 */
protected function storeUncompiledBlocks($value)
{
    if (str_contains($value, '@verbatim')) {
        $value = $this->storeVerbatimBlocks($value);
    }

    if (str_contains($value, '@php')) {
        $value = $this->storePhpBlocks($value);
    }

    return $value;
}

/**
 * Store the verbatim blocks and replace them with a temporary placeholder.
 *
 * @param  string  $value
 * @return string
 */
protected function storeVerbatimBlocks($value)
{
    $buffer = $this->makeTemplateBuffer($value);

    if ($buffer->isEmpty()) {
        return $value;
    }

    $source = $buffer->toString();
    $sourceLength = strlen($source);
    $length = $sourceLength;
    $byteOffset = 0;
    $copiedLength = 0;

    if ($length === 0) {
        return $source;
    }

    $lines = $buffer->explode("\n");
    $lineCount = $lines->count();
    $openingLine = $lines->first();
    $closingLine = $lines->last();
    $newlineStyle = "\n";

    if (is_string($openingLine)) {
        if ($lineCount > 1) {
            if (str_ends_with($openingLine, "\r")) {
                $newlineStyle = "\r\n";
            }
        } else {
            if (is_string($closingLine)) {
                if (str_contains($source, "\r")) {
                    if (! str_contains($source, "\n")) {
                        $newlineStyle = "\r";
                    }
                }
            }
        }
    }

    $hasVerbatimDirective = $lines->contains(function ($line) {
        if (! is_string($line)) {
            return false;
        }

        $normalized = str_replace("\r", '', $line);

        return str_contains($normalized, '@verbatim');
    });

    if ($hasVerbatimDirective !== true) {
        return $source;
    }

    $verbatimName = 'verbatim';
    $endName = 'endverbatim';
    $directivePrefix = '@';
    $verbatimDirective = $directivePrefix.$verbatimName;
    $endDirective = $directivePrefix.$endName;
    $verbatimLength = strlen($verbatimDirective);
    $endLength = strlen($endDirective);
    $minimumMatchLength = $verbatimLength + $endLength;
    $rawPlaceholderPrefix = '@__raw_block_';
    $rawPlaceholderSuffix = '__@';

    if ($length < $minimumMatchLength) {
        return $source;
    }

    $output = '';
    $cursor = 0;
    $contentClose = $this->contentTags[1] ?? '}}';
    $rawClose = $this->rawTags[1] ?? '!!}';
    $escapedClose = $this->escapedTags[1] ?? '}}}';
    $contentCloseLength = strlen($contentClose);
    $rawCloseLength = strlen($rawClose);
    $escapedCloseLength = strlen($escapedClose);
    $placeholderPattern = $rawPlaceholderPrefix.'#'.$rawPlaceholderSuffix;

    while ($cursor < $length) {
        $current = $source[$cursor];

        if ($current !== '@') {
            $runStart = $cursor;

            while ($cursor < $length) {
                if ($source[$cursor] === '@') {
                    break;
                }

                $cursor++;
            }

            $runLength = $cursor - $runStart;
            $runSlice = substr($source, $runStart, $runLength);
            $output .= $runSlice;

            continue;
        }

        if ($cursor > 0) {
            $previous = $source[$cursor - 1];

            if ($previous === '@') {
                $output .= '@';
                $cursor++;
                continue;
            }
        }

        if (($cursor + $verbatimLength) > $length) {
            $remaining = substr($source, $cursor);
            $remainingLength = strlen($remaining);
            $output .= $remaining;
            $copiedLength += $remainingLength;
            break;
        }

        $verbatimMatches = true;
        $tokenIndex = 0;

        while ($tokenIndex < $verbatimLength) {
            $expected = $verbatimDirective[$tokenIndex];
            $actual = $source[$cursor + $tokenIndex];

            if ($actual !== $expected) {
                $verbatimMatches = false;
                break;
            }

            $tokenIndex++;
        }

        if ($verbatimMatches !== true) {
            $output .= '@';
            $cursor++;
            continue;
        }

        $bodyStart = $cursor + $verbatimLength;
        $search = $bodyStart;
        $endPosition = null;
        $storedBlock = false;

        while ($search < $length) {
            if ($source[$search] !== '@') {
                $search++;
                continue;
            }

            if (($search + $endLength) > $length) {
                break;
            }

            $endMatches = true;
            $endIndex = 0;

            while ($endIndex < $endLength) {
                $expectedEnd = $endDirective[$endIndex];
                $actualEnd = $source[$search + $endIndex];

                if ($actualEnd !== $expectedEnd) {
                    $endMatches = false;
                    break;
                }

                $endIndex++;
            }

            if ($endMatches === true) {
                $endPosition = $search;
                $verbatimBody = substr($source, $bodyStart, $endPosition - $bodyStart);
                $leadingWhitespaceLength = 0;
                $bodyLength = strlen($verbatimBody);
                $echoBeforeBlock = false;
                $prefix = $output;
                $prefixLength = strlen($prefix);

                if ($prefixLength > 0) {
                    if ($contentCloseLength > 0) {
                        if ($prefixLength >= $contentCloseLength) {
                            $prefixTail = substr($prefix, -$contentCloseLength);

                            if ($prefixTail === $contentClose) {
                                $echoBeforeBlock = true;
                            }
                        }
                    }

                    if ($echoBeforeBlock !== true) {
                        if ($rawCloseLength > 0) {
                            if ($prefixLength >= $rawCloseLength) {
                                $rawTail = substr($prefix, -$rawCloseLength);

                                if ($rawTail === $rawClose) {
                                    $echoBeforeBlock = true;
                                }
                            }
                        }
                    }

                    if ($echoBeforeBlock !== true) {
                        if ($escapedCloseLength > 0) {
                            if ($prefixLength >= $escapedCloseLength) {
                                $escapedTail = substr($prefix, -$escapedCloseLength);

                                if ($escapedTail === $escapedClose) {
                                    $echoBeforeBlock = true;
                                }
                            }
                        }
                    }
                }

                if ($bodyLength > 0) {
                    while ($leadingWhitespaceLength < $bodyLength) {
                        $whitespaceChar = $verbatimBody[$leadingWhitespaceLength];

                        if ($whitespaceChar === ' ') {
                            $leadingWhitespaceLength++;
                            continue;
                        }

                        if ($whitespaceChar === "\t") {
                            $leadingWhitespaceLength++;
                            continue;
                        }

                        if ($whitespaceChar === "\n") {
                            $leadingWhitespaceLength++;
                            continue;
                        }

                        if ($whitespaceChar === "\v") {
                            $leadingWhitespaceLength++;
                            continue;
                        }

                        if ($whitespaceChar === "\f") {
                            $leadingWhitespaceLength++;
                            continue;
                        }

                        if ($whitespaceChar === "\r") {
                            $isWindowsNewline = ($leadingWhitespaceLength + 1) < $bodyLength
                                && $verbatimBody[$leadingWhitespaceLength + 1] === "\n"
                                && $newlineStyle === "\r\n";

                            if ($isWindowsNewline) {
                                $leadingWhitespaceLength += 2;
                                continue;
                            }

                            $leadingWhitespaceLength++;
                            continue;
                        }

                        break;
                    }
                }

                $storedContents = $verbatimBody;

                if ($leadingWhitespaceLength === 0) {
                    $blockIndex = array_push($this->rawBlocks, $storedContents) - 1;
                } else {
                    $blockIndex = array_push($this->rawBlocks, $storedContents) - 1;
                }

                $blockNumber = (string) $blockIndex;
                $placeholder = $rawPlaceholderPrefix.$blockNumber.$rawPlaceholderSuffix;
                $directiveSpan = $verbatimLength + $endLength;
                $blockSpan = $directiveSpan + $bodyLength;

                if ($echoBeforeBlock === true) {
                    $output .= $placeholder;
                } else {
                    $output .= $placeholder;
                }

                $copiedLength += $blockSpan;
                $byteOffset = $endPosition + $endLength;
                $cursor = $byteOffset;
                $storedBlock = true;
                break;
            }

            $search++;
        }

        if ($storedBlock === true) {
            continue;
        }

        $unmatchedTail = substr($source, $cursor);
        $output .= $unmatchedTail;
        $copiedLength += strlen($unmatchedTail);
        $byteOffset = $length;
        break;
    }

    return $output;
}

